import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";

export type DonationCampaignNonprofitCause = {
  /** The URL to the banner showing the cause that the nonprofit organization supports. */
  bannerUrl?: string;
  /** The unique identifier of the nonprofit cause. This value is generated by Adyen. */
  causeId?: string;
  /** The description of the cause that the nonprofit supports. */
  description?: string;
  /** The URL to the website of the nonprofit organization. */
  globalWebsiteUrl?: string;
  /**
   * The United Nations Sustainable Development Goals (UN SDGs) supported by the nonprofit
   * organization, specified in the format `unsdg_<number>`, where the number is the number of the
   * UN SDG. For example, **unsdg_1**.
   */
  goals?: string[];
  /** The URL to the logo of the nonprofit organization. */
  logoUrl?: string;
  /** The name of the nonprofit organization. */
  nonprofitName?: string;
  /** The URL to the terms and conditions of the nonprofit organization. */
  termsAndConditionsUrl?: string;
};

export const donationCampaignNonprofitCauseSchema: Schema<DonationCampaignNonprofitCause> =
  s.object<DonationCampaignNonprofitCause>({
    bannerUrl: s.optional(s.string()),
    causeId: s.optional(s.string()),
    description: s.optional(s.string()),
    globalWebsiteUrl: s.optional(s.string()),
    goals: s.optional(s.array(s.string())),
    logoUrl: s.optional(s.string()),
    nonprofitName: s.optional(s.string()),
    termsAndConditionsUrl: s.optional(s.string()),
  });
